"use client";

import type { Meta, StoryObj } from "@storybook/nextjs-vite";
import { fn } from "storybook/test";

import { InventisRoCard } from "./ro-card/InventisRoCard";
import { FIGMA_RO_CARD_FILE_BASE } from "./ro-card/figma";

const sharedArgs = {
  customerName: "Mr.Kim",
  statusLabel: "Draft",
  vehicle: "2023 Toyota Camry XSE",
  roNumber: "KCS-452",
  assignee: "Lucas",
  timeStart: "10:30 am",
  timeEnd: "11:30 am",
  serviceType: "Brake Service",
  onMenuClick: fn(),
};

const meta = {
  id: "pattern-ro-card",
  title: "Pattern/RO Card",
  component: InventisRoCard,
  tags: ["!autodocs"],
  args: {
    ...sharedArgs,
    type: "default" as const,
  },
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: `Inventis DS **RO(작업) 카드** — Figma \`Type=Default | Action | Schedule\`. ([Figma 파일](${FIGMA_RO_CARD_FILE_BASE}))`,
      },
    },
  },
} satisfies Meta<typeof InventisRoCard>;

export default meta;

type Story = StoryObj<typeof meta>;

/** Figma Type=Default — 칸반 열 폭(~233px) 기준 컴팩트 카드 */
export const Default: Story = {
  name: "Default",
  decorators: [
    (Story) => (
      <div className="w-[233px]">
        <Story />
      </div>
    ),
  ],
};

/** Figma Type=Action — 큐 패널 폭(~366px), SMS / Call / Check In 푸터 */
export const WithActionFooter: Story = {
  name: "With Action Footer",
  args: {
    type: "action",
    onSendSms: fn(),
    onCall: fn(),
    onCheckIn: fn(),
  },
  decorators: [
    (Story) => (
      <div className="w-[366px] max-w-full">
        <Story />
      </div>
    ),
  ],
};

/** Figma Type=Schedule — 앰버 좌측 강조, 차량·시간 위주 */
export const Schedule: Story = {
  name: "Schedule",
  render: () => (
    <div className="w-[388px] max-w-full">
      <InventisRoCard
        type="schedule"
        customerName="Mr.Lee"
        vehicle="2022 Ford F-150"
        timeStart="10:30 am"
        timeEnd="11:30 am"
        onMenuClick={fn()}
      />
    </div>
  ),
};

/** Default + 진행률 행 (Figma progress 플래그) */
export const WithProgress: Story = {
  name: "With Progress",
  args: {
    showProgress: true,
    progressValue: 50,
  },
  decorators: Default.decorators,
};

"use client";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { cn } from "@/bases/radix/lib/utils";
import {
  Car,
  Loader2,
  Mail,
  MoreVertical,
  Phone,
  Ticket,
  Timer,
  User,
  Wrench,
} from "lucide-react";
import * as React from "react";

export type InventisRoCardType = "default" | "action" | "schedule";

export type InventisRoCardProps = {
  /** Figma `Type=` — Default(컴팩트) · Action(푸터 CTA) · Schedule(앰버 강조) */
  type?: InventisRoCardType;
  className?: string;
  customerName: string;
  /** RO 상태 (예: Draft) — emerald 배지; `schedule` 에서는 생략 */
  statusLabel?: string;
  vehicle: string;
  roNumber?: string;
  assignee?: string;
  timeStart?: string;
  timeEnd?: string;
  serviceType?: string;
  showProgress?: boolean;
  /** 0–100 */
  progressValue?: number;
  onMenuClick?: () => void;
  onSendSms?: () => void;
  onCall?: () => void;
  onCheckIn?: () => void;
};

function RowIcon({
  icon: Icon,
  children,
}: {
  icon: React.ComponentType<{ className?: string }>;
  children: React.ReactNode;
}) {
  return (
    <div className="flex h-5 items-center gap-2">
      <span
        className="inline-flex size-4 shrink-0 items-center justify-center"
        aria-hidden
      >
        <Icon className="text-muted-foreground size-4" />
      </span>
      <span className="text-foreground min-w-0 flex-1 truncate text-sm leading-5">
        {children}
      </span>
    </div>
  );
}

/**
 * Inventis DS RO 카드 (Figma ❖ RO — Default / Action / Schedule).
 */
export function InventisRoCard({
  type = "default",
  className,
  customerName,
  statusLabel,
  vehicle,
  roNumber,
  assignee,
  timeStart,
  timeEnd,
  serviceType,
  showProgress,
  progressValue = 50,
  onMenuClick,
  onSendSms,
  onCall,
  onCheckIn,
}: InventisRoCardProps) {
  const showStatus = Boolean(statusLabel) && type !== "schedule";

  const shell = cn(
    "flex flex-col overflow-hidden border shadow-xs",
    type === "schedule"
      ? "rounded-[var(--radius-xs)] border border-l-[3px] border-amber-200 border-l-amber-600 bg-amber-50 dark:border-amber-800 dark:border-l-amber-500 dark:bg-amber-950/25"
      : type === "action"
        ? "bg-popover text-popover-foreground rounded-lg"
        : "bg-card text-card-foreground rounded-lg",
    className,
  );

  const header = (
    <div className="flex w-full items-center justify-between gap-2 px-4 pt-3 pb-2">
      <div className="flex min-w-0 flex-1 items-center gap-2">
        <span className="text-foreground flex min-h-5 min-w-0 items-center truncate text-[18px] leading-tight font-semibold tracking-tight">
          {customerName}
        </span>
        {showStatus ? (
          <Badge
            className="h-5 shrink-0 border-transparent bg-emerald-100 px-2 py-0 text-xs leading-none font-medium text-emerald-800 hover:bg-emerald-100 dark:bg-emerald-950 dark:text-emerald-300"
            variant="secondary"
          >
            {statusLabel}
          </Badge>
        ) : null}
      </div>
      <Button
        type="button"
        variant="ghost"
        className="text-muted-foreground hover:text-foreground size-5 shrink-0 rounded-md p-0 [&_svg]:pointer-events-none"
        aria-label="More options"
        onPointerDown={(e) => e.stopPropagation()}
        onClick={onMenuClick}
      >
        <MoreVertical className="size-4" aria-hidden />
      </Button>
    </div>
  );

  const body = (
    <div className="flex flex-col gap-1 px-4 pb-2">
      <RowIcon icon={Car}>{vehicle}</RowIcon>
      {roNumber ? <RowIcon icon={Ticket}>{roNumber}</RowIcon> : null}
      {assignee && type !== "schedule" ? (
        <RowIcon icon={User}>{assignee}</RowIcon>
      ) : null}
      {timeStart ? (
        <div className="flex h-5 items-center gap-2">
          <span
            className="inline-flex size-4 shrink-0 items-center justify-center"
            aria-hidden
          >
            <Timer className="text-muted-foreground size-4" />
          </span>
          <span className="text-foreground min-w-0 flex-1 truncate text-sm leading-5">
            {timeStart}
            {timeEnd ? (
              <>
                {" "}
                <span aria-hidden>—</span> {timeEnd}
              </>
            ) : null}
          </span>
        </div>
      ) : null}
      {serviceType && type !== "schedule" ? (
        <RowIcon icon={Wrench}>{serviceType}</RowIcon>
      ) : null}
      {showProgress ? (
        <div className="flex min-h-5 items-center gap-2 pt-0.5">
          <span
            className="inline-flex size-4 shrink-0 items-center justify-center"
            aria-hidden
          >
            <Loader2 className="text-muted-foreground size-4 animate-spin" />
          </span>
          <Progress
            value={progressValue}
            className="bg-muted h-1 max-w-full min-w-0 flex-1 rounded-full"
          />
        </div>
      ) : null}
    </div>
  );

  const footer =
    type === "action" ? (
      <div className="bg-muted/40 flex gap-2 border-t px-4 py-2">
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="flex-1 gap-1.5"
          onClick={onSendSms}
        >
          <Mail className="size-4" />
          Send SMS
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="flex-1 gap-1.5"
          onClick={onCall}
        >
          <Phone className="size-4" />
          Call
        </Button>
        <Button
          type="button"
          size="sm"
          className="min-w-[120px] flex-1"
          onClick={onCheckIn}
        >
          Check In
        </Button>
      </div>
    ) : null;

  return (
    <article className={shell}>
      {header}
      {body}
      {footer}
    </article>
  );
}

/**
 * Inventis DS RO Card — Figma 참조.
 * Variants: node 26837:1510 (Type=Default | Action | Schedule)
 */

export const FIGMA_RO_CARD_FILE_KEY = "MvGuEwW5KUn5VcpSEWm2ve";

export const FIGMA_RO_CARD_FILE_BASE = `https://www.figma.com/design/${FIGMA_RO_CARD_FILE_KEY}/260303_Inventis-DS--Shadcn-ui`;

export const FIGMA_RO_CARD_VARIANTS_SECTION = "26837:1510";

/** Type=Default */
export const FIGMA_RO_CARD_TYPE_DEFAULT = "26660:21178";

/** Type=Action */
export const FIGMA_RO_CARD_TYPE_ACTION = "26808:231302";

/** Type=Schedule */
export const FIGMA_RO_CARD_TYPE_SCHEDULE = "26808:232225";

/** RO Popover */
export const FIGMA_RO_CARD_POPOVER = "26808:248588";

/** 독스 페이지 */
export const FIGMA_RO_CARD_DOC_PAGE = "26837:1538";

/** 예시 페이지 */
export const FIGMA_RO_CARD_PAGE_DEFAULT = "26837:28366";
export const FIGMA_RO_CARD_PAGE_ACTION = "26837:29493";
export const FIGMA_RO_CARD_PAGE_SCHEDULE = "26837:30514";

export const FIGMA_RO_CARD_DOC_NODE_IDS = [
  "26837:1510",
  "26837:1979",
  "26837:1573",
  "26837:56295",
  "26837:1538",
  "26837:56296",
  "26837:30514",
  "26837:28366",
  "26837:29493",
] as const;

export function figmaRoCardNodeUrl(nodeId: string): string {
  return `${FIGMA_RO_CARD_FILE_BASE}?node-id=${encodeURIComponent(nodeId.replace(":", "-"))}&m=dev`;
}

import * as React from "react";

const tableStyle: React.CSSProperties = {
  width: "100%",
  borderCollapse: "collapse",
  fontSize: "13px",
  margin: "16px 0",
};

export function RoCardCodeStructureTable() {
  const rows = [
    {
      file: "ro-card/InventisRoCard.tsx",
      role: "`type` · 헤더(이름·Draft 배지·더보기) · 본문 행 · Action 푸터",
    },
    {
      file: "ro-card/figma.ts",
      role: "Figma node-id · Variants(26837:1510)",
    },
  ];
  return (
    <table style={tableStyle}>
      <thead>
        <tr style={{ borderBottom: "1px solid var(--border)" }}>
          <th style={{ textAlign: "left", padding: "8px 12px", width: "42%" }}>
            파일
          </th>
          <th style={{ textAlign: "left", padding: "8px 12px" }}>역할</th>
        </tr>
      </thead>
      <tbody>
        {rows.map((r) => (
          <tr key={r.file} style={{ borderBottom: "1px solid var(--border)" }}>
            <td style={{ padding: "8px 12px", verticalAlign: "top" }}>
              <code style={{ fontSize: "12px" }}>{r.file}</code>
            </td>
            <td
              style={{
                padding: "8px 12px",
                color: "var(--muted-foreground)",
                verticalAlign: "top",
              }}
            >
              {r.role}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

/** 사이드바(북마크) 표기·순서 = `ro-card-pattern.stories.tsx` export 순서와 동일 */
export function RoCardVariantsTable() {
  const rows = [
    {
      sidebarLabel: "Default",
      figma: "Type=Default",
      desc: "칸반 열 폭(~233px) 기준 컴팩트 카드",
    },
    {
      sidebarLabel: "With Action Footer",
      figma: "Type=Action",
      desc: "큐 패널 폭(~366px), Send SMS / Call / Check In 푸터",
    },
    {
      sidebarLabel: "Schedule",
      figma: "Type=Schedule",
      desc: "앰버 좌측 강조, 차량·시간 위주",
    },
    {
      sidebarLabel: "With Progress",
      figma: "Default + progress",
      desc: "Default 카드에 진행률 행(`showProgress`)",
    },
  ];
  return (
    <table style={tableStyle}>
      <thead>
        <tr style={{ borderBottom: "1px solid var(--border)" }}>
          <th style={{ textAlign: "left", padding: "8px 12px", width: "26%" }}>
            스토리북 스토리
          </th>
          <th style={{ textAlign: "left", padding: "8px 12px", width: "22%" }}>
            Figma
          </th>
          <th style={{ textAlign: "left", padding: "8px 12px" }}>설명</th>
        </tr>
      </thead>
      <tbody>
        {rows.map((r) => (
          <tr
            key={r.sidebarLabel}
            style={{ borderBottom: "1px solid var(--border)" }}
          >
            <td style={{ padding: "8px 12px" }}>
              <strong>{r.sidebarLabel}</strong>
            </td>
            <td
              style={{
                padding: "8px 12px",
                color: "var(--muted-foreground)",
                fontSize: "12px",
              }}
            >
              <code>{r.figma}</code>
            </td>
            <td
              style={{
                padding: "8px 12px",
                color: "var(--muted-foreground)",
              }}
            >
              {r.desc}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
